const root = '/home/cassandra/tradecloseout';
const {createRequire} = require('node:module');
const {randomUUID,randomBytes,createHash} = require('node:crypto');
const fs = require('node:fs');
const req = createRequire(`${root}/apps/api/package.json`);
const {Test} = req('@nestjs/testing');
const {Pool} = req('pg');
const {ValidationPipe} = req('@nestjs/common');
const Redis = req('ioredis');
const pick = (m,k) => m[k] || m.default[k];
const compiled = `${root}/apps/api/dist/apps/api/src`;
const {AppModule} = require(`${compiled}/app.module.js`);
const {TenantDbService} = require(`${compiled}/database/tenant-db.service.js`);
const {ProblemJsonExceptionFilter} = require(`${compiled}/common/filters/problem-json.filter.js`);
const {VisibilityProjectionInterceptor} = require(`${compiled}/common/interceptors/visibility-projection.interceptor.js`);
const results=[];
(async()=>{
 process.env.NODE_ENV='test';
 process.env.REDIS_URL ||= 'redis://127.0.0.1:6379';
 const helper=await import(`${root}/packages/db/test/helpers/disposable-database.ts`);
 const fixtures=await import(`${root}/packages/db/test/helpers/fixtures.ts`);
 await pick(helper,'withDisposableDatabase')(async ({admin,app:pool})=>{
  const {userId,tenants:[a]}=await pick(fixtures,'seedTenants')(admin);
  await admin.query(`INSERT INTO memberships(id,org_id,user_id,role,status) VALUES($1,$2,$3,'R-OWNER','ACTIVE')`,[randomUUID(),a.orgId,userId]);
  const token=randomBytes(32).toString('hex'),csrf=randomBytes(24).toString('hex');
  const hash=x=>createHash('sha256').update(x).digest('hex');
  const session=randomUUID();
  await admin.query(`INSERT INTO sessions(id,user_id,token_hash,csrf_token_hash,active_org_id,expires_at) VALUES($1,$2,$3,$4,$5,now()+interval '1 day')`,[session,userId,hash(token),hash(csrf),a.orgId]);
  const module=await Test.createTestingModule({imports:[AppModule]})
   .overrideProvider(Pool).useValue(pool)
   .overrideProvider(TenantDbService).useValue(new TenantDbService(pool)).compile();
  const app=module.createNestApplication({logger:false});
  app.use(req('cookie-parser')());
  app.useGlobalPipes(new ValidationPipe({whitelist:true,transform:true}));
  app.useGlobalFilters(new ProblemJsonExceptionFilter());
  try {
   await app.listen(0,'127.0.0.1');
   const base=await app.getUrl();
   async function get(label,path,cookie=token){
    const response=await fetch(base+path,{headers:{Cookie:`tc_session=${cookie}`}});
    const body=await response.json().catch(()=>null);
    if(label==='consultant_projection')results.push({label,status:response.status,internalSettingsVisible:body?.settings_json?.internal_note==='synthetic confidential note'});
    else results.push({label,status:response.status,body:Array.isArray(body)?{count:body.length,projectIds:body.map(x=>x.id)}:body});
   }
   await get('owner_auth_me','/api/v1/auth/me');
   await get('owner_auth_orgs','/api/v1/auth/orgs');
   await get('versioned_work_items','/api/v1/work-items');
   await get('unversioned_work_items','/work-items');
   await get('versioned_commissioning',`/api/v1/projects/${a.projectIds[0]}/commissioning/tab-worksheets`);
   await get('unversioned_commissioning',`/projects/${a.projectIds[0]}/commissioning/tab-worksheets`);
   const party=randomUUID(),grant=randomUUID(),guestToken=randomBytes(32).toString('hex');
   await admin.query(`INSERT INTO parties(id,org_id,name,types,status) VALUES($1,$2,'Scoped external client',ARRAY['CLIENT'],'ACTIVE')`,[party,a.orgId]);
   await admin.query(`INSERT INTO guest_grants(id,org_id,project_id,party_id,target_email,grant_type,role,capabilities,scope_json,token_hash,expires_at,created_by) VALUES($1,$2,$3,$4,'probe@example.invalid','CLIENT_VIEW','R-CLIENT',ARRAY['project.read','asset.read'],'{}',$5,now()+interval '1 day',$6)`,[grant,a.orgId,a.projectIds[0],party,hash(randomUUID()),userId]);
   await admin.query(`INSERT INTO sessions(id,user_id,token_hash,csrf_token_hash,active_org_id,guest_grant_id,expires_at) VALUES($1,$2,$3,$4,$5,$6,now()+interval '1 day')`,[randomUUID(),userId,hash(guestToken),hash(csrf),a.orgId,grant]);
   await get('guest_project_list_scoped_to_project_0','/api/v1/projects',guestToken);
   await get('guest_reads_other_project',`/api/v1/projects/${a.projectIds[1]}`,guestToken);
   await admin.query(`UPDATE projects SET settings_json=$1 WHERE id=$2`,[JSON.stringify({internal_note:'synthetic confidential note',supplier_price:123}),a.projectIds[0]]);
   await admin.query(`UPDATE guest_grants SET role='R-CONSULT' WHERE id=$1`,[grant]);
   await get('consultant_projection',`/api/v1/projects/${a.projectIds[0]}`,guestToken);
   const portalResponse=await fetch(base+`/api/v1/submissions/${randomUUID()}/recipients/${randomUUID()}/decision`,{method:'POST',headers:{Cookie:`tc_session=${token}`,'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:JSON.stringify({decision:'ACCEPTED',remarks:'Payload emitted by current guest page'})});
   results.push({label:'current_guest_page_decision_payload',status:portalResponse.status,body:await portalResponse.json()});
   let verificationPackageNo=0;
   async function seedSubmission() {
    const pkg=randomUUID(),sub=randomUUID(),recipient=randomUUID();
    await admin.query(`INSERT INTO handover_packages(id,org_id,project_id,title,status,snapshot_checksum,created_by,version_no) VALUES($1,$2,$3,'Verification','READY',$4,$5,$6)`,[pkg,a.orgId,a.projectIds[0],'a'.repeat(64),userId,++verificationPackageNo]);
    await admin.query(`INSERT INTO submissions(id,org_id,project_id,package_id,method,status,created_by) VALUES($1,$2,$3,$4,'PORTAL','SUBMITTED',$5)`,[sub,a.orgId,a.projectIds[0],pkg,userId]);
    await admin.query(`INSERT INTO submission_recipients(id,org_id,project_id,submission_id,recipient_party_id,role,status) VALUES($1,$2,$3,$4,$5,'CLIENT_REP','SENT')`,[recipient,a.orgId,a.projectIds[0],sub,party]);
    return {sub,recipient};
   }
   for(const [label,body] of [
    ['decision_accept',{decision:'ACCEPT'}],
    ['decision_reject',{decision:'REJECT',remarks:'Independent rejection explanation'}],
    ['decision_exceptions',{decision:'ACCEPT_WITH_EXCEPTIONS',remarks:'Accept with documented scope exceptions'}],
    ['unknown_decision',{decision:'UNRECOGNIZED_VALUE'}]
   ]) {
    const seeded=await seedSubmission();
    const response=await fetch(base+`/api/v1/submissions/${seeded.sub}/recipients/${seeded.recipient}/decision`,{method:'POST',headers:{Cookie:`tc_session=${token}`,'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:JSON.stringify(body)});
    const reply=await response.json();
    const persisted=await admin.query(`SELECT decision,status FROM submission_recipients WHERE id=$1`,[seeded.recipient]);
    results.push({label,status:response.status,replyStatus:reply.status||reply.code,persisted:persisted.rows[0]});
   }
   const procUser=randomUUID(),procToken=randomBytes(32).toString('hex');
   await admin.query(`INSERT INTO users(id,name,status) VALUES($1,'Procurement member','ACTIVE')`,[procUser]);
   await admin.query(`INSERT INTO memberships(id,org_id,user_id,role,status) VALUES($1,$2,$3,'R-PROC','ACTIVE')`,[randomUUID(),a.orgId,procUser]);
   await admin.query(`INSERT INTO sessions(id,user_id,token_hash,csrf_token_hash,active_org_id,expires_at) VALUES($1,$2,$3,$4,$5,now()+interval '1 day')`,[randomUUID(),procUser,hash(procToken),hash(csrf),a.orgId]);
   const updateBody=JSON.stringify({displayName:'Synthetic guest privilege probe',rowVersion:1,brandColor:'#0F172A',watermarkEnabled:false,allowSelfApproval:false,defaultRetentionMonths:96});
   const before=await fetch(base+'/api/v1/orgs/current',{method:'PATCH',headers:{Cookie:`tc_session=${procToken}`,'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:updateBody});
   results.push({label:'procurement_direct_org_update',status:before.status});
   const issued=await fetch(base+`/api/v1/projects/${a.projectIds[0]}/guest-grants`,{method:'POST',headers:{Cookie:`tc_session=${procToken}`,'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:JSON.stringify({partyId:party,email:'probe@example.invalid',grantType:'CLIENT',role:'R-OWNER',capabilities:['org.manage']})});
   const issuedBody=await issued.json();
   results.push({label:'procurement_issues_owner_guest_grant',status:issued.status,grantCreated:!!issuedBody.grantId});
   if(issuedBody.grantId) {
    const guestUser=randomUUID(),escalatedToken=randomBytes(32).toString('hex');
    await admin.query(`INSERT INTO users(id,name,status) VALUES($1,'External guest without membership','ACTIVE')`,[guestUser]);
    await admin.query(`INSERT INTO sessions(id,user_id,token_hash,csrf_token_hash,active_org_id,guest_grant_id,expires_at) VALUES($1,$2,$3,$4,$5,$6,now()+interval '1 day')`,[randomUUID(),guestUser,hash(escalatedToken),hash(csrf),a.orgId,issuedBody.grantId]);
    const after=await fetch(base+'/api/v1/orgs/current',{method:'PATCH',headers:{Cookie:`tc_session=${escalatedToken}`,'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:updateBody});
    const persisted=await admin.query(`SELECT display_name FROM organisations WHERE id=$1`,[a.orgId]);
    results.push({label:'issued_guest_org_update',status:after.status,changed:persisted.rows[0].display_name==='Synthetic guest privilege probe'});
   }
   for(const [label,issuer,body] of [
    ['owner_cannot_override_guest_role',token,{partyId:party,email:'probe@example.invalid',grantType:'CLIENT',role:'R-OWNER'}],
    ['owner_cannot_exceed_guest_capabilities',token,{partyId:party,email:'probe@example.invalid',grantType:'CLIENT',capabilities:['org.manage']}],
    ['normal_owner_client_grant',token,{partyId:party,email:'probe@example.invalid',grantType:'CLIENT'}],
    ['normal_procurement_supplier_grant',procToken,{partyId:party,email:'probe@example.invalid',grantType:'SUPPLIER'}]
   ]){
    const r=await fetch(base+`/api/v1/projects/${a.projectIds[0]}/guest-grants`,{method:'POST',headers:{Cookie:`tc_session=${issuer}`,'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:JSON.stringify(body)});
    const b=await r.json();results.push({label,status:r.status,grantCreated:!!b.grantId});
   }
   const legacy=randomUUID(),legacyUser=randomUUID(),legacyToken=randomBytes(32).toString('hex');
   await admin.query(`INSERT INTO users(id,name,status) VALUES($1,'Legacy unsafe grant guest','ACTIVE')`,[legacyUser]);
   await admin.query(`INSERT INTO guest_grants(id,org_id,project_id,party_id,target_email,grant_type,role,capabilities,scope_json,token_hash,expires_at,created_by) VALUES($1,$2,$3,$4,'legacy@example.invalid','CLIENT_VIEW','R-OWNER',ARRAY['org.manage'],'{}',$5,now()+interval '1 day',$6)`,[legacy,a.orgId,a.projectIds[0],party,hash(randomUUID()),userId]);
   await admin.query(`INSERT INTO sessions(id,user_id,token_hash,csrf_token_hash,active_org_id,guest_grant_id,expires_at) VALUES($1,$2,$3,$4,$5,$6,now()+interval '1 day')`,[randomUUID(),legacyUser,hash(legacyToken),hash(csrf),a.orgId,legacy]);
   const legacyResponse=await fetch(base+'/api/v1/orgs/current',{method:'PATCH',headers:{Cookie:`tc_session=${legacyToken}`,'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:updateBody});
   results.push({label:'legacy_owner_role_guest_cannot_administer_org',status:legacyResponse.status});
   const response=await fetch(base+'/api/v1/auth/logout',{method:'POST',headers:{Cookie:`tc_session=${token}`,'X-CSRF-Token':csrf}});
   results.push({label:'owner_logout',status:response.status});
   const row=await admin.query(`SELECT revoked_at FROM sessions WHERE id=$1`,[session]);
   results.push({label:'logout_persisted_revocation',revoked:row.rows[0]?.revoked_at!=null});
  }finally{
   app.get(Redis).disconnect();
   await app.close();
  }
 });
 fs.writeFileSync('/tmp/tradecloseout-followup2-http-results.json',JSON.stringify(results,null,2)+'\n');
 for(const result of results)console.log(JSON.stringify(result));
})().catch(e=>{console.error('PROBE_FAILED',e.message);process.exitCode=1});

