const root='/home/cassandra/tradecloseout';
const {createRequire}=require('node:module');
const {randomUUID,createHash}=require('node:crypto');
const fs=require('node:fs');
const req=createRequire(`${root}/apps/api/package.json`);
req('@nestjs/common');
const Redis=req('ioredis');
const compiled=`${root}/apps/api/dist/apps/api/src`;
const {TenantDbService}=require(`${compiled}/database/tenant-db.service.js`);
const {AssetsService}=require(`${compiled}/modules/assets/assets.service.js`);
const {ProjectsService}=require(`${compiled}/modules/projects/projects.service.js`);
const {PartiesService}=require(`${compiled}/modules/parties/parties.service.js`);
const {ReviewsService}=require(`${compiled}/modules/reviews/reviews.service.js`);
const {ChecklistsService}=require(`${compiled}/modules/checklists/checklists.service.js`);
const {WorkItemsService}=require(`${compiled}/modules/work-items/work-items.service.js`);
const {HandoverService}=require(`${compiled}/modules/handover/handover.service.js`);
const {IdentityController}=require(`${compiled}/modules/identity/identity.controller.js`);
const {IdentityModule}=require(`${compiled}/modules/identity/identity.module.js`);
const pick=(m,k)=>m[k]||m.default[k];
const results=[];
async function probe(label,fn){try{results.push({label,result:await fn()});}catch(e){results.push({label,error:{code:e.code,message:e.message,response:e.response}});}}
(async()=>{
 const h=await import(`${root}/packages/db/test/helpers/disposable-database.ts`);
 const f=await import(`${root}/packages/db/test/helpers/fixtures.ts`);
 await pick(h,'withDisposableDatabase')(async({admin,app})=>{
  const {userId,tenants:[a]}=await pick(f,'seedTenants')(admin);
  const org=a.orgId,project=a.projectIds[0];
  const otherUser=randomUUID();
  await admin.query(`INSERT INTO users(id,name,status) VALUES($1,'Independent reviewer','ACTIVE')`,[otherUser]);
  const ctx={orgId:org,userId,actorType:'MEMBER',orgRole:'R-OWNER',ip:'127.0.0.1',userAgent:'audit-probe',requestId:randomUUID()};
  const db=new TenantDbService(app),assets=new AssetsService(app),projects=new ProjectsService(app),parties=new PartiesService(db),reviews=new ReviewsService(db),checklists=new ChecklistsService(app),workItems=new WorkItemsService(app);
  const asset=randomUUID(),snapshot=randomUUID(),requirement=randomUUID(),object=randomUUID(),doc=randomUUID(),version=randomUUID(),party=randomUUID();
  const sha='a'.repeat(64);
  await admin.query(`INSERT INTO assets(id,org_id,project_id,tag,name,category_key,created_by) VALUES($1,$2,$3,'AHU-1','AHU-1','HVAC_AHU',$4)`,[asset,org,project,userId]);
  await probe('passport_after_projection_fix',async()=>{const r=await assets.getEquipmentPassport(ctx,project,asset);return {succeeded:!!r};});
  await admin.query(`INSERT INTO checklist_snapshots(id,org_id,project_id,version_no,status,resolved_payload_json,provenance_json,source_json,checksum,created_by) VALUES($1,$2,$3,1,'ACTIVE','{}','{}','{}',$4,$5)`,[snapshot,org,project,sha,userId]);
  await admin.query(`INSERT INTO requirements(id,org_id,project_id,current_snapshot_id,requirement_key,group_key,title,doc_type_key,mandatory,status,reviewer_role) VALUES($1,$2,$3,$4,'REQ-1','HVAC','Manual','MANUAL',true,'NOT_STARTED','R-OWNER')`,[requirement,org,project,snapshot]);
  await admin.query(`INSERT INTO storage_objects(id,org_id,bucket,object_key,mime,size_bytes,observed_size_bytes,sha256,status,provider_version_id) VALUES($1,$2,'vault',$3,'application/pdf',1024,1024,$4,'READY','v1')`,[object,org,`uploads/${object}`,sha]);
  await admin.query(`INSERT INTO documents(id,org_id,project_id,title,doc_type_key,category_key,status,created_by) VALUES($1,$2,$3,'Manual','MANUAL','EQUIPMENT','ACTIVE',$4)`,[doc,org,project,userId]);
  await admin.query(`INSERT INTO document_versions(id,org_id,project_id,document_id,version_no,revision_code,object_id,file_status,review_status,issue_date,uploaded_by) VALUES($1,$2,$3,$4,1,'R0',$5,'READY','NOT_SUBMITTED',CURRENT_DATE,$6)`,[version,org,project,doc,object,otherUser]);
  await admin.query(`UPDATE documents SET latest_version_id=$1 WHERE id=$2`,[version,doc]);
  await probe('canonical_review_submission_real_schema',()=>reviews.submitReview({...ctx,actorType:'USER'},requirement,{documentVersionId:version}));
  await probe('review_state_after_submission',async()=>{const r=await admin.query(`SELECT review_status FROM document_versions WHERE id=$1`,[version]);return r.rows[0];});
  await probe('pending_waiver_work_queue',async()=>{
   await checklists.requestWaiver(ctx,requirement,'Scope exception needs independent approval');
   const r=await workItems.listWorkItems(ctx,{projectId:project});
   return {waiverCount:r.counts?.waivers,types:r.items?.map(x=>x.type)};
  });
  await admin.query(`INSERT INTO parties(id,org_id,name,types,status) VALUES($1,$2,'Supplier',ARRAY['SUPPLIER_OEM'],'ACTIVE')`,[party,org]);
  await probe('generic_guest_grant_default_enum',async()=>{const r=await parties.createGuestGrant({...ctx,actorType:'USER'},project,{partyId:party,email:'probe@example.invalid'});const q=await admin.query('SELECT grant_type,role,capabilities FROM guest_grants WHERE id=$1',[r.grantId]);return{created:!!r.grantId,profile:q.rows[0]};});
  await admin.query(`INSERT INTO contracts(id,org_id,project_id,reference,title,value_paise,retention_bps,status,created_by) VALUES($1,$2,$3,'ZERO','Zero retention',1000000,0,'ACTIVE',$4)`,[randomUUID(),org,project,userId]);
  await probe('project_dashboard_zero_retention',async()=>{const r=await projects.getProjectDashboard(ctx,project);return {retentionAtRiskPaise:r.retentionAtRiskPaise};});
  const archive=randomUUID(),archiveObject=randomUUID(),key=`archives/${archive}.zip`;
  await admin.query(`INSERT INTO storage_objects(id,org_id,bucket,object_key,mime,size_bytes,sha256,status,provider_version_id) VALUES($1,$2,'vault',$3,'application/zip',2048,$4,'READY','v1')`,[archiveObject,org,key,sha]);
  await admin.query(`INSERT INTO archive_exports(id,org_id,project_id,status,archive_sha256,verification_receipt_json) VALUES($1,$2,$3,'COMPLETED',$4,$5)`,[archive,org,project,sha,JSON.stringify({artifact:{objectId:archiveObject,objectKey:key,bucket:'vault',providerVersionId:'v1',sizeBytes:2048,sha256:sha}})]);
  let signed=false;const handover=new HandoverService(app,{createSignedDownloadUrl:async()=>{signed=true;return'https://probe.invalid';}});
  await probe('archive_missing_observed_size_only',async()=>{await handover.getArchiveExport(ctx,project,archive);return{signed};});
 });
 process.env.NODE_ENV='test';process.env.ENABLE_DEBUG_OTP='true';delete process.env.REDIS_URL;
 const provider=Reflect.getMetadata('providers',IdentityModule).find(p=>p.provide===Redis);
 const fallback=provider.useFactory();
 const controller=new IdentityController({connect:async()=>{throw new Error('UNEXPECTED_DATABASE_ACCESS');}},fallback,{},{});
 await probe('in_memory_OTP_immediate_valid_code',async()=>{
  const identifier=`audit-${randomUUID()}@example.invalid`;
  const challenge=await controller.requestOtp({identifier},{});
  try{await controller.verifyOtp({identifier,challengeId:challenge.challengeId,code:challenge.debugOtp},{headers:{}},{cookie(){}});return{verified:true};}
  catch(e){return{verified:false,acceptedBeforeDatabase:e.message==='UNEXPECTED_DATABASE_ACCESS',code:e.response?.code||e.message};}
 });
 await probe('in_memory_OTP_request_budget',async()=>{
  const identifier=`budget-${randomUUID()}@example.invalid`;
  let accepted=0,limited=false;
  for(let n=0;n<7;n++){try{await controller.requestOtp({identifier},{});accepted++;}catch(e){if(e.getStatus?.()===429)limited=true;else throw e;}}
  return{accepted,limited,rateCounter:await fallback.get(`rl:otp:req:${identifier}`)};
 });
 await probe('in_memory_OTP_expiry_after_301_seconds',async()=>{
  const identifier=`expiry-${randomUUID()}@example.invalid`;
  const challenge=await controller.requestOtp({identifier},{});
  const originalNow=Date.now;
  Date.now=()=>originalNow()+301000;
  try{
   await controller.verifyOtp({identifier,challengeId:challenge.challengeId,code:challenge.debugOtp},{headers:{}},{cookie(){}});
   return{expiredChallengeAccepted:true};
  }catch(e){return{expiredChallengeAccepted:e.message==='UNEXPECTED_DATABASE_ACCESS',code:e.response?.code||e.message};}
  finally{Date.now=originalNow;}
 });
 process.env.ENABLE_DEBUG_OTP='false';
 const redis=new Redis(process.env.REDIS_URL||'redis://127.0.0.1:6379');
 const identifier=`audit-${randomUUID()}@example.invalid`;
 let rejectFirst,entered;
 const enteredPromise=new Promise(r=>entered=r);let sends=0,secondCode;
 const mail={sendOtpEmail:async(_id,code)=>{sends++;if(sends===1){entered();return new Promise((_r,reject)=>rejectFirst=reject);}secondCode=code;}};
 const live=new IdentityController({connect:async()=>{throw new Error('UNEXPECTED_DATABASE_ACCESS');}},redis,{},mail);
 const first=live.requestOtp({identifier},{}).catch(()=>null);
 await enteredPromise;
 const firstId=await redis.get(`otp:alias:${identifier}`);
 const second=await live.requestOtp({identifier},{});
 rejectFirst(new Error('controlled first provider failure'));await first;
 await probe('older_delivery_failure_deletes_new_generation_alias',async()=>{
  const alias=await redis.get(`otp:alias:${identifier}`);
  try{await live.verifyOtp({identifier,challengeId:second.challengeId,code:secondCode},{headers:{}},{cookie(){}});return{aliasPresent:!!alias,verified:true};}
  catch(e){return{aliasPresent:!!alias,verified:false,acceptedBeforeDatabase:e.message==='UNEXPECTED_DATABASE_ACCESS',code:e.response?.code||e.message};}
 });
 const keys=[`rl:otp:req:${identifier}`,`otp:alias:${identifier}`,`otp:challenge:${identifier}`,`otp:challenge:${firstId}`,`otp:challenge:${second.challengeId}`,`otp:attempts:${firstId}`,`otp:attempts:${second.challengeId}`];
 await redis.del(...keys);await redis.quit();
 fs.writeFileSync('/tmp/tradecloseout-followup2-domain-results.json',JSON.stringify(results,null,2)+'\n');
 for(const result of results)console.log(JSON.stringify(result));
})().catch(e=>{console.error('PROBE_FAILED',e.code||'',e.message);process.exitCode=1;});

