(async()=>{
 const {PDFDocument,PDFName,PDFString,PDFDict}=req('pdf-lib');
 const engine=await import(process.cwd()+'/packages/pdf-engine/src/sanitise-pdf.ts');
 const worker=await import(process.cwd()+'/apps/worker/src/queues/pdf-stream-compiler.ts');
 const inspect=engine.inspectAndSanitisePdf||engine.default.inspectAndSanitisePdf;
 const check=worker.sanitizeAndCheckPdfBomb||worker.default.sanitizeAndCheckPdfBomb;
 const dir=await fs.mkdtemp(path.join(os.tmpdir(),'tc-pdf-followup2-'));
 const results=[];
 try{
  for(const chained of [false,true]){
   const doc=await PDFDocument.create(),page=doc.addPage();
   const js=doc.context.register(doc.context.obj({S:PDFName.of('JavaScript'),JS:PDFString.of('void 0')}));
   doc.catalog.set(PDFName.of('OpenAction'),js);
